package com.app.entity;
import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="society_inspections") @Data @Builder @NoArgsConstructor @AllArgsConstructor
public class SocietyInspection {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="account_id",nullable=false) private Account account; @Column(nullable=false,length=180) private String title; private String location; private LocalDateTime scheduledFor; private LocalDateTime completedAt; @Column(nullable=false,length=20) @Builder.Default private String result="PENDING"; @Column(length=4000) private String checklist; @Column(length=2000) private String notes; @Column(length=2000) private String failureAction; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="work_order_id") private SocietyWorkOrder workOrder; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by_user_id",nullable=false) private User createdBy; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="completed_by_user_id") private User completedBy; @Column(nullable=false,updatable=false) @Builder.Default private LocalDateTime createdAt=LocalDateTime.now(); @Column(nullable=false) @Builder.Default private LocalDateTime updatedAt=LocalDateTime.now(); @PreUpdate void touch(){updatedAt=LocalDateTime.now();}}
